import random

def evaluate(current_reputation, observation, observation_action, my_history, round_num):
    # Update reputation based on observed action with weighted recent behavior
    if observation_action == 'cooperate':
        new_reputation = min(1.0, current_reputation + 0.3)
    else:
        new_reputation = max(-1.0, current_reputation - 0.3)

    # Decay slightly to weight recent actions more heavily
    new_reputation = new_reputation * 0.9

    return new_reputation

def decide(recipient_reputation, round_num, my_history):
    # Cooperate based on recipient's reputation with some stochasticity
    # Base decision on indirect reputation, not direct reciprocity
    if recipient_reputation > 0.2:
        return random.random() < 0.85
    elif recipient_reputation < -0.2:
        return random.random() < 0.15
    else:
        return random.random() < 0.5
